window.resolveFiberAsset = function(path){
  return (window.FIBER_INLINE_ASSETS && window.FIBER_INLINE_ASSETS[path]) || path;
};
(function(){
  function fixImg(img){
    if(!img || !img.getAttribute) return;
    var src = img.getAttribute('src') || '';
    if(src.indexOf('assets/fiber/') === 0){
      var resolved = window.resolveFiberAsset(src);
      if(resolved !== src) img.setAttribute('src', resolved);
    }
  }
  function scan(root){
    if(!root) return;
    if(root.tagName === 'IMG') fixImg(root);
    if(root.querySelectorAll) root.querySelectorAll('img[src^="assets/fiber/"]').forEach(fixImg);
  }
  scan(document);
  if(typeof MutationObserver !== 'undefined'){
    new MutationObserver(function(muts){
      muts.forEach(function(m){
        m.addedNodes && m.addedNodes.forEach(function(n){
          if(n && n.nodeType === 1) scan(n);
        });
        if(m.type === 'attributes' && m.target && m.target.tagName === 'IMG') fixImg(m.target);
      });
    }).observe(document.documentElement || document, {
      childList:true, subtree:true, attributes:true, attributeFilter:['src']
    });
  }
  document.addEventListener('DOMContentLoaded', function(){ scan(document); });
})();
